// The alert names the task and the run, so both have to be there.
const body = $input.first().json.body;

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value);
const isText = (value) => typeof value === 'string' && value.length > 0;
const isObject = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const errors = [];
const expect = (ok, message) => { if (!ok) errors.push(message); };

expect(isObject(body), 'the body must be a JSON object');
const failure = isObject(body) ? body : {};
expect(failure.kind === 'pipeline_failure', 'kind must be "pipeline_failure"');
expect(failure.schema_version === 1, 'schema_version must be 1');
for (const field of ['dag_id', 'task_id', 'run_id', 'failed_at']) {
  expect(isText(failure[field]), `${field} must be text`);
}
expect(failure.error === null || typeof failure.error === 'string', 'error must be text or null');

return [{ json: { valid: errors.length === 0, errors, failure } }];

const { valid, failure } = $input.first().json;
if (!valid) return [];

// Settings come from the environment of the n8n container (see .env.example).
// A missing one stops the workflow, and the error workflow reports it.
const setting = (name) => {
  const value = $env[name];
  if (value === undefined || value === '') throw new Error(`${name} is not set`);
  return value;
};
const numberSetting = (name) => {
  const value = Number(setting(name));
  if (!Number.isFinite(value)) throw new Error(`${name} must be a number`);
  return value;
};
const money = (value) => value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const whole = (value) => value.toLocaleString('en-US');

setting('NOTIFICATIONS_TELEGRAM_CHAT_ID');
setting('NOTIFICATIONS_EMAIL_FROM');
setting('NOTIFICATIONS_EMAIL_TO');
const airflow = setting('NOTIFICATIONS_AIRFLOW_URL').replace(/\/$/, '');

const failedAt = new Date(failure.failed_at).toLocaleString('en-US', {
  timeZone: 'America/Guatemala', dateStyle: 'medium', timeStyle: 'short',
});
const tries = failure.try_number ? ` after ${failure.try_number} tries` : '';
const log = `${airflow}/dags/${encodeURIComponent(failure.dag_id)}/runs/` +
  `${encodeURIComponent(failure.run_id)}/tasks/${encodeURIComponent(failure.task_id)}`;

const lines = [
  'Quetzal lakehouse - pipeline failure',
  '',
  `Task ${failure.task_id} of ${failure.dag_id} failed${tries}, on ${failedAt} (Guatemala).`,
  `Run: ${failure.run_id}`,
  `Error: ${failure.error ?? 'not given'}`,
  '',
  `Task log: ${log}`,
];
return [{ json: { subject: `Quetzal lakehouse: task ${failure.task_id} failed`, text: lines.join('\n') } }];

// Both channels are tried even when one fails, so one broken channel does
// not silence the other. A failure is raised here, after both, and the error
// workflow reports it.
const failures = [];
for (const node of ['Send to Telegram', 'Send email']) {
  const error = $(node).first().json.error;
  if (error) failures.push(`${node}: ${typeof error === 'string' ? error : JSON.stringify(error)}`);
}
if (failures.length) throw new Error(failures.join('; '));
return [{ json: { delivered: true } }];
